#!/usr/bin/env python3
"""Builds the expanded question pack (IDs numbered 5001+) from reviewable fact tables.

Why tables: a scholar can verify one table row (e.g. a surah's verse count, an Imam's burial
place) instead of reviewing many generated questions one by one. Every generated question is
status "draft" until reviewed.

Run:   python3 tools/build-question-pack.py
It keeps the hand-written questions (IDs below 5000) in data/questions.js, replaces the
generated ones, then re-exports data/questions.csv and runs the validator.
"""
import json
import os
import random
import subprocess

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.join(HERE, '..')
rng = random.Random(1446)
AR = str.maketrans('0123456789', '٠١٢٣٤٥٦٧٨٩')


def ar(n):
    return str(n).translate(AR)


PREFIX = {'quran': 'QUR', 'prophet': 'PRO', 'masumeen': 'IMM', 'aqeedah': 'AQD', 'fiqh': 'FQH', 'akhlaq': 'AKH',
          'duas': 'DUA', 'history': 'HIS', 'places': 'PLC', 'occasions': 'OCC', 'prophets': 'NBI',
          'karbala': 'KRB', 'science': 'SCI', 'social': 'SOC', 'general': 'GEN'}
counters = {}
out = []


def add(cat, diff, question, correct, wrongs, explanation, source):
    opts = [correct] + [w for w in wrongs if w != correct][:3]
    assert len(opts) == 4 and len(set(opts)) == 4, (question, opts)
    p = PREFIX[cat]
    counters[p] = counters.get(p, 5000) + 1
    out.append({'id': f'{p}-{counters[p]:04d}', 'category': cat, 'difficulty': diff, 'question': question,
                'options': opts, 'answer': 0, 'explanation': explanation, 'source': source, 'status': 'draft'})


def others(pool, correct, k=3, exclude=()):
    cand = [x for x in dict.fromkeys(pool) if x != correct and x not in exclude]
    return rng.sample(cand, k)


def near(n, k=3, offsets=(1, -1, 2, -2, 3, -3, 4, 5), lo=1, hi=10 ** 6):
    offs = list(offsets)
    rng.shuffle(offs)
    res = []
    for d in offs:
        v = n + d
        if lo <= v <= hi and v != n and v not in res:
            res.append(v)
        if len(res) == k:
            break
    return res


